files=json.loads("{\"replay_explain.py\":\"\\\"\\\"\\\"Bounded literal differences for the local synthetic Explorer replay command.\\\"\\\"\\\"\\nimport copy\\nimport json\\nimport math\\nimport os\\nfrom pathlib import Path\\nimport stat\\nimport sys\\n\\nfrom scenarios import json_equivalent, replay_result, run_scenario\\n\\nDIFFERENCE_LIMIT = 32\\n_MISSING = object()\\n\\n\\ndef _json_type(value):\\n    if value is None:\\n        return \\\"null\\\"\\n    if type(value) is bool:\\n        return \\\"boolean\\\"\\n    if type(value) in (int, float):\\n        return \\\"number\\\"\\n    if isinstance(value, str):\\n        return \\\"string\\\"\\n    if isinstance(value, list):\\n        return \\\"array\\\"\\n    if isinstance(value, dict):\\n        return \\\"object\\\"\\n    raise TypeError(\\\"Expected a JSON value\\\")\\n\\n\\ndef _side(value):\\n    if value is _MISSING:\\n        return {\\\"present\\\": False}\\n    return {\\\"present\\\": True, \\\"type\\\": _json_type(value), \\\"value\\\": value}\\n\\n\\ndef _pointer(parent, key):\\n    return parent + \\\"/\\\" + str(key).replace(\\\"~\\\", \\\"~0\\\").replace(\\\"/\\\", \\\"~1\\\")\\n\\n\\ndef _walk(expected, actual, pointer=\\\"\\\"):\\n    if expected is _MISSING or actual is _MISSING:\\n        yield {\\n            \\\"path\\\": pointer,\\n            \\\"kind\\\": \\\"unexpected\\\" if expected is _MISSING else \\\"missing\\\",\\n            \\\"expected\\\": _side(expected),\\n            \\\"actual\\\": _side(actual),\\n        }\\n        return\\n    if json_equivalent(expected, actual):\\n        return\\n    expected_type, actual_type = _json_type(expected), _json_type(actual)\\n    if expected_type != actual_type:\\n        yield {\\\"path\\\": pointer, \\\"kind\\\": \\\"type\\\",\\n               \\\"expected\\\": _side(expected), \\\"actual\\\": _side(actual)}\\n    elif isinstance(expected, dict):\\n        for key in sorted(expected.keys() | actual.keys()):\\n            yield from _walk(expected.get(key, _MISSING),\\n                             actual.get(key, _MISSING), _pointer(pointer, key))\\n    elif isinstance(expected, list):\\n        for index in range(max(len(expected), len(actual))):\\n            left = expected[index] if index < len(expected) else _MISSING\\n            right = actual[index] if index < len(actual) else _MISSING\\n            yield from _walk(left, right, _pointer(pointer, index))\\n    else:\\n        yield {\\\"path\\\": pointer, \\\"kind\\\": \\\"value\\\",\\n               \\\"expected\\\": _side(expected), \\\"actual\\\": _side(actual)}\\n\\n\\ndef explain_replay(value):\\n    \\\"\\\"\\\"Return the ordinary replay reply plus at most 32 detached differences.\\n\\n    Input is a finite decoded JSON export. This describes local reproduction,\\n    not provenance, causation or authority. Numeric comparison stays with the\\n    maintained Explorer comparator.\\n    \\\"\\\"\\\"\\n    # Refuse nonfinite or excessively deep values before computing a report.\\n    json.dumps(value, allow_nan=False)\\n    actual = copy.deepcopy(value)\\n    reply = replay_result(actual)\\n    expected = run_scenario(**actual[\\\"request\\\"])\\n    differences = []\\n    truncated = False\\n    for difference in _walk(expected, actual):\\n        if len(differences) == DIFFERENCE_LIMIT:\\n            truncated = True\\n            break\\n        differences.append(difference)\\n    return {**reply, \\\"difference_limit\\\": DIFFERENCE_LIMIT,\\n            \\\"differences\\\": differences, \\\"differences_truncated\\\": truncated}\\n\\n\\ndef _finite_float(text):\\n    value = float(text)\\n    if not math.isfinite(value):\\n        raise ValueError(\\\"Non-finite JSON numbers are not supported\\\")\\n    return value\\n\\n\\ndef _reject_constant(_text):\\n    raise ValueError(\\\"Non-finite JSON numbers are not supported\\\")\\n\\n\\ndef _read_export(path, max_bytes):\\n    # The descriptor check avoids consuming devices or pipes. It does not\\n    # promise exclusion of concurrent regular-file writers or directory races.\\n    flags = os.O_RDONLY | getattr(os, \\\"O_BINARY\\\", 0) | getattr(os, \\\"O_NONBLOCK\\\", 0)\\n    fd = os.open(path, flags)\\n    try:\\n        if not stat.S_ISREG(os.fstat(fd).st_mode):\\n            raise ValueError(\\\"Replay explanation requires a regular file\\\")\\n        with os.fdopen(fd, \\\"rb\\\") as source:\\n            fd = None\\n            raw = source.read(max_bytes + 1)\\n    finally:\\n        if fd is not None:\\n            os.close(fd)\\n    if len(raw) > max_bytes:\\n        raise ValueError(f\\\"Export exceeds {max_bytes} bytes\\\")\\n    return json.loads(raw.decode(\\\"utf-8\\\"), parse_float=_finite_float,\\n                      parse_constant=_reject_constant)\\n\\n\\ndef run_explanation(path: Path, max_bytes: int, stdout=None, stderr=None):\\n    \\\"\\\"\\\"Deliver one complete prepared report; 0 match, 1 mismatch, 2 refusal.\\\"\\\"\\\"\\n    output = sys.stdout if stdout is None else stdout\\n    errors = sys.stderr if stderr is None else stderr\\n    try:\\n        reply = explain_replay(_read_export(path, max_bytes))\\n        text = json.dumps(reply, ensure_ascii=False, allow_nan=False, indent=2) + \\\"\\\\n\\\"\\n    except (OSError, ValueError, TypeError, RecursionError) as exc:\\n        print(f\\\"Replay explanation rejected: {exc}\\\", file=errors)\\n        return 2\\n    try:\\n        count = output.write(text)\\n        if type(count) is not int or count != len(text):\\n            raise OSError(\\\"Incomplete stdout write\\\")\\n        output.flush()\\n    except (OSError, ValueError, UnicodeError) as exc:\\n        # The CLI exits immediately. Closing only its actual stdout suppresses\\n        # a second shutdown flush; caller-supplied streams remain caller-owned.\\n        if output is sys.stdout:\\n            try:\\n                output.close()\\n            except OSError:\\n                pass\\n        print(f\\\"Replay explanation output failed: {exc}\\\", file=errors)\\n        return 2\\n    return 0 if reply[\\\"matches\\\"] else 1\\n\",\"explorer.py\":\"#!/usr/bin/env python3\\n\\\"\\\"\\\"Zero-dependency loopback-only explorer and deterministic scenario CLI.\\\"\\\"\\\"\\nimport argparse\\nimport json\\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\\nfrom pathlib import Path\\nfrom typing import cast\\nfrom urllib.parse import urlsplit\\n\\nfrom scenarios import DISCLAIMER, SCENARIOS, replay_result, run_scenario\\n\\nROOT = Path(__file__).resolve().parent\\nMAX_BODY = 262144\\nBODY_READ_TIMEOUT = 5.0\\n\\n\\nclass Handler(BaseHTTPRequestHandler):\\n    def respond(self, status, body, content_type=\\\"application/json; charset=utf-8\\\"):\\n        raw = body if isinstance(body, bytes) else json.dumps(body, allow_nan=False).encode()\\n        self.send_response(status)\\n        self.send_header(\\\"Content-Type\\\", content_type)\\n        self.send_header(\\\"Content-Length\\\", str(len(raw)))\\n        self.send_header(\\\"Cache-Control\\\", \\\"no-store\\\")\\n        self.send_header(\\\"X-Content-Type-Options\\\", \\\"nosniff\\\")\\n        self.send_header(\\\"Content-Security-Policy\\\", \\\"default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; frame-ancestors 'none'\\\")\\n        self.end_headers()\\n        self.wfile.write(raw)\\n\\n    def local_request(self):\\n        host = self.headers.get(\\\"Host\\\", \\\"\\\")\\n        port = cast(ThreadingHTTPServer, self.server).server_port\\n        allowed = {f\\\"127.0.0.1:{port}\\\", f\\\"localhost:{port}\\\"}\\n        origin = self.headers.get(\\\"Origin\\\")\\n        if host not in allowed or (origin is not None and origin != \\\"http://\\\" + host):\\n            self.respond(403, {\\\"error\\\": \\\"Loopback same-origin requests only\\\"})\\n            return False\\n        return True\\n\\n    def do_GET(self):\\n        if not self.local_request():\\n            return\\n        route = urlsplit(self.path).path\\n        if route == \\\"/api/scenarios\\\":\\n            self.respond(200, {\\\"disclaimer\\\": DISCLAIMER, \\\"scenarios\\\": [\\n                {\\\"id\\\": key, \\\"label\\\": label, \\\"description\\\": description}\\n                for key, (label, description) in SCENARIOS.items()]})\\n        elif route in {\\\"/\\\", \\\"/app.js\\\", \\\"/style.css\\\"}:\\n            name, mime = {\\\"/\\\": (\\\"index.html\\\", \\\"text/html\\\"), \\\"/app.js\\\": (\\\"app.js\\\", \\\"text/javascript\\\"),\\n                          \\\"/style.css\\\": (\\\"style.css\\\", \\\"text/css\\\")}[route]\\n            self.respond(200, (ROOT / \\\"web\\\" / name).read_bytes(), mime + \\\"; charset=utf-8\\\")\\n        else:\\n            self.respond(404, {\\\"error\\\": \\\"Not found\\\"})\\n\\n    def do_POST(self):\\n        if not self.local_request():\\n            return\\n        if self.path not in {\\\"/api/run\\\", \\\"/api/replay\\\"}:\\n            self.respond(404, {\\\"error\\\": \\\"Not found\\\"})\\n            return\\n        try:\\n            if self.headers.get_all(\\\"Transfer-Encoding\\\") is not None:\\n                self.respond(400, {\\\"error\\\": \\\"Transfer-Encoding is not supported; use Content-Length\\\"})\\n                return\\n            lengths = self.headers.get_all(\\\"Content-Length\\\", [])\\n            if not lengths:\\n                self.respond(411, {\\\"error\\\": \\\"Content-Length is required\\\"})\\n                return\\n            if len(lengths) != 1:\\n                self.respond(400, {\\\"error\\\": \\\"Provide exactly one Content-Length\\\"})\\n                return\\n            length_text = lengths[0].strip(\\\" \\\\t\\\")\\n            if not length_text.isascii() or not length_text.isdecimal():\\n                self.respond(400, {\\\"error\\\": \\\"Content-Length must contain ASCII decimal digits\\\"})\\n                return\\n            # Compare decimal text before conversion, including arbitrarily\\n            # many leading zeroes, without Python's integer-string limit.\\n            length_text = length_text.lstrip(\\\"0\\\") or \\\"0\\\"\\n            maximum = str(MAX_BODY)\\n            if (length_text == \\\"0\\\" or len(length_text) > len(maximum)\\n                    or (len(length_text) == len(maximum) and length_text > maximum)):\\n                self.respond(413, {\\\"error\\\": \\\"Body must be between 1 and 262144 bytes\\\"})\\n                return\\n            length = int(length_text)\\n            if self.headers.get(\\\"Content-Type\\\", \\\"\\\").split(\\\";\\\")[0] != \\\"application/json\\\":\\n                self.respond(415, {\\\"error\\\": \\\"Use application/json\\\"})\\n                return\\n            previous_timeout = self.connection.gettimeout()\\n            self.connection.settimeout(BODY_READ_TIMEOUT)\\n            try:\\n                raw = self.rfile.read(length)\\n            except TimeoutError:\\n                self.respond(408, {\\\"error\\\": \\\"Timed out waiting for the complete request body\\\"})\\n                return\\n            finally:\\n                self.connection.settimeout(previous_timeout)\\n            if len(raw) != length:\\n                self.respond(400, {\\\"error\\\": \\\"Request body is shorter than Content-Length\\\"})\\n                return\\n            def reject_constant(value):\\n                raise ValueError(\\\"Non-finite JSON is not supported\\\")\\n            value = json.loads(raw, parse_constant=reject_constant)\\n            if self.path == \\\"/api/replay\\\":\\n                result = replay_result(value)\\n            else:\\n                if not isinstance(value, dict) or set(value) != {\\\"scenario\\\", \\\"include_approval\\\", \\\"include_ack\\\"}:\\n                    raise ValueError(\\\"Provide scenario and both fixture switches\\\")\\n                if not isinstance(value[\\\"scenario\\\"], str):\\n                    raise ValueError(\\\"Scenario must be a string\\\")\\n                result = run_scenario(**value)\\n            self.respond(200, result)\\n        except (ValueError, TypeError, KeyError, RecursionError) as exc:\\n            self.respond(400, {\\\"error\\\": str(exc)[:200]})\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(description=DISCLAIMER)\\n    commands = parser.add_subparsers(dest=\\\"command\\\", required=True)\\n    serve = commands.add_parser(\\\"serve\\\", help=\\\"Loopback-only browser UI\\\")\\n    serve.add_argument(\\\"--port\\\", type=int, default=8765)\\n    run = commands.add_parser(\\\"run\\\", help=\\\"Export a fixed synthetic case as JSON\\\")\\n    run.add_argument(\\\"scenario\\\", choices=SCENARIOS)\\n    run.add_argument(\\\"--without-approval\\\", action=\\\"store_true\\\")\\n    run.add_argument(\\\"--without-ack\\\", action=\\\"store_true\\\")\\n    replay = commands.add_parser(\\\"replay\\\", help=\\\"Recompute and compare a local JSON export\\\")\\n    replay.add_argument(\\\"file\\\", type=Path)\\n    replay.add_argument(\\\"--explain\\\", action=\\\"store_true\\\",\\n                        help=\\\"Report up to 32 literal differing JSON paths\\\")\\n    args = parser.parse_args()\\n    if args.command == \\\"serve\\\":\\n        with ThreadingHTTPServer((\\\"127.0.0.1\\\", args.port), Handler) as server:\\n            print(f\\\"Synthetic explorer: http://127.0.0.1:{server.server_port}\\\\n{DISCLAIMER}\\\", flush=True)\\n            try:\\n                server.serve_forever()\\n            except KeyboardInterrupt:\\n                pass\\n    elif args.command == \\\"run\\\":\\n        print(json.dumps(run_scenario(args.scenario, not args.without_approval, not args.without_ack), indent=2))\\n    else:\\n        if args.explain:\\n            from replay_explain import run_explanation\\n            raise SystemExit(run_explanation(args.file, MAX_BODY))\\n        try:\\n            if args.file.stat().st_size > MAX_BODY:\\n                raise ValueError(\\\"Export exceeds 262144 bytes\\\")\\n            result = replay_result(json.loads(args.file.read_text()))\\n        except (ValueError, TypeError) as exc:\\n            parser.exit(2, str(exc) + \\\"\\\\n\\\")\\n        print(json.dumps(result, indent=2))\\n        if not result[\\\"matches\\\"]:\\n            raise SystemExit(1)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\",\"EXPLORER.md\":\"# TowerOps local synthetic scenario explorer\\n\\nResearch simulation only; fixture identities are not real authority. No live feeds, model/Strands calls, SDK dependency, real clearances, or aviation safety claim. Existing `towerops.py` is byte-for-byte unchanged from public baseline `e8fa18e`.\\n\\n## First run\\n\\nPython 3.12+ and a modern browser; **no pip install is needed for the app**.\\n\\n```sh\\npython explorer.py serve --port 8765\\n```\\n\\nOpen http://127.0.0.1:8765 . Choose **Approval + acknowledgement**, leave the two simulated-fixture boxes checked, and Run. The projected conflict changes true→false after simulated actuation. Scrub projected minutes to compare constant-velocity paths. Gate times are synthetic seconds, separate from projected minutes.\\n\\nChoose **Missing acknowledgement** and Run without reloading: rejection `ack_missing`, unchanged world, no actuation event. The displayed result and download always represent the last completed run, not an unrun selection. Withholding checkboxes cannot supply missing fixtures or bypass engine gates.\\n\\nOther fixed cases: missing approval, acknowledgement dated after dispatch cutoff (`ack_late`), stale observation, changed world hash, acknowledgement for wrong advisory, expired proposal. Every refusal retains the exact pre-gate world. Fixed identities are `FIXTURE-A`, `FIXTURE-B`, `FIXTURE-CONTROLLER-NOT-AUTHORITY`.\\n\\n## Export and replay\\n\\nExport JSON after a run. Select that file under **Replay exported JSON**: the backend reexecutes its fixed scenario and fixture switches and compares the entire result. It accepts equivalent finite JSON numbers (1001 versus 1001.0), never boolean→number coercion. Change `after.version` in a copy and replay: MISMATCH. Malformed formats/unknown scenarios are rejected. Uploaded files are not saved or used as arbitrary engine input.\\n\\nThe replay status belongs to the currently selected file. Selecting another export retires earlier file reads and replay responses, including their errors; clearing the input clears the status. An already-sent request may still finish, but cannot replace the newer verdict. Replay does not change the displayed scenario result or its JSON export.\\n\\nReplay is reproducibility under this local engine, not authenticity. The hash chain is not a signature or external custody anchor; someone can construct another valid fixed-fixture export. No replay result grants real authority.\\n\\nCLI (shell redirection saves real engine output):\\n\\n```sh\\npython explorer.py run approved > approved.json\\npython explorer.py run missing_ack > missing_ack.json\\npython explorer.py run approved --without-approval\\npython explorer.py replay approved.json\\n```\\n\\nReplay exits 0 for match, 1 for mismatch, 2 for malformed input.\\n\\n## Tests\\n\\nStandard-library engine/control + real HTTP suite:\\n\\n```sh\\npython -m unittest -v test_explorer\\n```\\n\\nIt exercises all eight cases × four fixture-switch combinations, exact no-actuation retention, full-export edits, JS numeric roundtrip, real HTTP run/replay, and invalid requests. No fabricated provider outputs.\\n\\nFocused Explorer replay-selection lifecycle tests (Node.js 20+; built-in modules only):\\n\\n```sh\\nnode tests/test_explorer_replay_selection.cjs\\n```\\n\\nThese controlled DOM/fetch tests cover superseded reads, responses, JSON bodies and errors, same-file reselection, clearing, current refusals and explicit recovery. They do not replace actual browser receiving.\\n\\nOptional actual browser acceptance:\\n\\n```sh\\npython -m pip install playwright\\npython -m playwright install chromium\\n# Linux images without browser libraries only:\\npython -m playwright install-deps chromium\\npython browser_acceptance.py\\n```\\n\\nChromium exercises all eight UI cases at desktop 1280×900 and mobile 390×844, sliders/SVG geometry, downloads, original replay, tampered replay, withheld controls, no horizontal overflow/page errors. Browser dependencies are test-only, not app dependencies. Logs/screenshots live in local `evidence/` when that directory exists.\\n\\n## HTTP scope\\n\\nBound to 127.0.0.1 only. Static routes `/`, `/app.js`, `/style.css`; GET `/api/scenarios`; POST `/api/run` with JSON `{ \\\"scenario\\\": \\\"approved\\\", \\\"include_approval\\\": true, \\\"include_ack\\\": true }`; POST `/api/replay` with a whole exported result. Fixed inputs only, 256KiB body cap, same-origin Host/Origin checks. This is a local development server, not a remotely deployed service. Ctrl+C stops it; no estate services are touched.\\n\\n## Getting the code\\n\\nEverything needed is in this repository (standard library only for the app). Either clone the branch, or apply the patch to a clean checkout of baseline `e8fa18e` (`main`):\\n\\n```sh\\ngit apply towerops-explorer-all.patch   # from a clean clone of main\\npython -m unittest -q                   # 8 tests\\npython explorer.py serve --port 8765\\n```\\n\\nA transfer zip of the same files (`towerops-explorer.zip`) runs the same way after extraction; compare its SHA-256 with the delivery report if you move it between machines.\\n\\n## Explain an Explorer replay mismatch\\n\\nUse the optional detailed report to locate differences in one saved export:\\n\\n```sh\\npython3 explorer.py replay approved.json --explain\\n```\\n\\nThe ordinary reply fields stay present. The report adds `difference_limit: 32`,\\n`differences` and `differences_truncated`. Each row names an RFC6901 JSON Pointer\\n(`~0` means a literal tilde and `~1` a literal slash), a missing/unexpected/type/value\\nkind, and literal expected/actual sides. A side with `present: false` is absent;\\n`present: true, type: \\\"null\\\", value: null` is an explicit null. Object keys are\\nvisited in sorted order and array indices in increasing order. A type difference\\nreports that subtree once. Values are complete, not shortened.\\n\\nFor the documented edited `after.version` copy, a row identifies `/after/version`.\\nFinite numerically equal integers and floats remain equal; booleans do not become\\nnumbers. The first 32 differences are returned. `differences_truncated: true`\\nmeans at least one more was found, not a total count. Paths describe differences\\nfrom the fixed local reproduction; they do not infer why an export changed or\\nauthenticate it. The existing reproducibility/authority caveats still apply.\\n\\nExplain mode reads one regular UTF-8 file, bounded to 262,144 bytes at the actual\\nread. It refuses malformed, excessively deep or nonfinite JSON, including overflow\\nnumbers, before report output. It follows the existing fixture request admission;\\nit does not accept arbitrary engine input. It neither writes the input nor opens\\nan output file. Concurrent file writers and adversarial directory changes are not\\nexcluded. Keep the original when redirecting stdout: a shell may truncate its\\ndestination before this command starts.\\n\\nExit 0 is a delivered matching report, 1 a delivered mismatch report, and 2 a\\nrefusal or stdout write/flush failure. The complete JSON is prepared first, but\\nbytes already written cannot be rolled back on output failure. Default replay\\nwithout `--explain`, its original decoding and exits, and the browser HTTP reply\\nremain unchanged.\\n\\nFocused standard-library tests:\\n\\n```sh\\npython3 -m unittest discover -s tests -p 'test_replay_explain.py' -v\\n```\\n\",\"tests/test_replay_explain.py\":\"\\\"\\\"\\\"Focused public API and actual CLI controls for Explorer replay explanations.\\\"\\\"\\\"\\nimport copy\\nimport io\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport subprocess\\nimport sys\\nimport tempfile\\nimport unittest\\n\\nfrom replay_explain import explain_replay, run_explanation\\nfrom scenarios import replay_result, run_scenario\\n\\nROOT = Path(__file__).resolve().parents[1]\\nMAX_BYTES = 262144\\n\\n\\nclass ReplayExplanationTests(unittest.TestCase):\\n    def setUp(self):\\n        self.export = run_scenario(\\\"approved\\\")\\n        self.directory = tempfile.TemporaryDirectory()\\n        self.addCleanup(self.directory.cleanup)\\n        self.path = Path(self.directory.name) / \\\"export 東京.json\\\"\\n\\n    def save(self, value=None):\\n        self.path.write_text(json.dumps(self.export if value is None else value),\\n                             encoding=\\\"utf-8\\\")\\n        return self.path\\n\\n    def cli(self, *args, stdout=subprocess.PIPE):\\n        env = {k: v for k, v in os.environ.items() if not k.startswith(\\\"PYTHON\\\")}\\n        env[\\\"PYTHONDONTWRITEBYTECODE\\\"] = \\\"1\\\"\\n        optimize = [\\\"-O\\\"] if sys.flags.optimize else []\\n        return subprocess.run([sys.executable, *optimize, \\\"-B\\\", str(ROOT / \\\"explorer.py\\\"),\\n                               \\\"replay\\\", *map(str, args)], cwd=self.directory.name,\\n                              env=env, stdout=stdout, stderr=subprocess.PIPE, timeout=15)\\n\\n    def test_match_and_finite_numeric_equivalence(self):\\n        actual = copy.deepcopy(self.export)\\n        actual[\\\"before\\\"][\\\"aircraft\\\"][0][\\\"x_nm\\\"] = -5\\n        report = explain_replay(actual)\\n        self.assertTrue(report[\\\"matches\\\"])\\n        self.assertEqual(report[\\\"differences\\\"], [])\\n        self.assertFalse(report[\\\"differences_truncated\\\"])\\n        self.assertEqual(report[\\\"difference_limit\\\"], 32)\\n        self.assertEqual({k: report[k] for k in replay_result(actual)}, replay_result(actual))\\n\\n    def test_literal_type_value_missing_null_and_pointer_order(self):\\n        actual = copy.deepcopy(self.export)\\n        actual[\\\"after\\\"][\\\"version\\\"] += 1\\n        actual[\\\"policy\\\"][\\\"horizon_min\\\"] = True\\n        del actual[\\\"rejection_reason\\\"]\\n        actual[\\\"z/~東京\\\"] = \\\"<literal>&\\\\nline\\\"\\n        report = explain_replay(actual)\\n        self.assertFalse(report[\\\"matches\\\"])\\n        self.assertEqual([(r[\\\"path\\\"], r[\\\"kind\\\"]) for r in report[\\\"differences\\\"]],\\n                         [(\\\"/after/version\\\", \\\"value\\\"), (\\\"/policy/horizon_min\\\", \\\"type\\\"),\\n                          (\\\"/rejection_reason\\\", \\\"missing\\\"), (\\\"/z~1~0東京\\\", \\\"unexpected\\\")])\\n        rows = report[\\\"differences\\\"]\\n        self.assertEqual(rows[1][\\\"expected\\\"][\\\"type\\\"], \\\"number\\\")\\n        self.assertEqual(rows[1][\\\"actual\\\"], {\\\"present\\\": True, \\\"type\\\": \\\"boolean\\\", \\\"value\\\": True})\\n        self.assertEqual(rows[2][\\\"expected\\\"], {\\\"present\\\": True, \\\"type\\\": \\\"null\\\", \\\"value\\\": None})\\n        self.assertEqual(rows[2][\\\"actual\\\"], {\\\"present\\\": False})\\n        self.assertEqual(rows[3][\\\"actual\\\"][\\\"value\\\"], \\\"<literal>&\\\\nline\\\")\\n\\n    def test_array_presence_and_subtree_type_are_explicit(self):\\n        actual = copy.deepcopy(self.export)\\n        missing = actual[\\\"before\\\"][\\\"aircraft\\\"].pop()\\n        report = explain_replay(actual)\\n        self.assertEqual(report[\\\"differences\\\"], [{\\n            \\\"path\\\": \\\"/before/aircraft/1\\\", \\\"kind\\\": \\\"missing\\\",\\n            \\\"expected\\\": {\\\"present\\\": True, \\\"type\\\": \\\"object\\\", \\\"value\\\": missing},\\n            \\\"actual\\\": {\\\"present\\\": False}}])\\n        actual = copy.deepcopy(self.export)\\n        actual[\\\"before\\\"][\\\"aircraft\\\"].append(None)\\n        report = explain_replay(actual)\\n        self.assertEqual(report[\\\"differences\\\"][0][\\\"path\\\"], \\\"/before/aircraft/2\\\")\\n        self.assertEqual(report[\\\"differences\\\"][0][\\\"kind\\\"], \\\"unexpected\\\")\\n        actual[\\\"before\\\"][\\\"aircraft\\\"] = \\\"not an array\\\"\\n        report = explain_replay(actual)\\n        self.assertEqual(len(report[\\\"differences\\\"]), 1)\\n        self.assertEqual(report[\\\"differences\\\"][0][\\\"kind\\\"], \\\"type\\\")\\n        self.assertEqual(report[\\\"differences\\\"][0][\\\"path\\\"], \\\"/before/aircraft\\\")\\n\\n    def test_limit_detects_more_without_claiming_total(self):\\n        actual = copy.deepcopy(self.export)\\n        for index in range(32):\\n            actual[f\\\"z{index:02}\\\"] = index\\n        exact = explain_replay(actual)\\n        self.assertEqual(len(exact[\\\"differences\\\"]), 32)\\n        self.assertFalse(exact[\\\"differences_truncated\\\"])\\n        actual[\\\"z32\\\"] = 32\\n        overflow = explain_replay(actual)\\n        self.assertEqual(overflow[\\\"differences\\\"], exact[\\\"differences\\\"])\\n        self.assertTrue(overflow[\\\"differences_truncated\\\"])\\n        self.assertNotIn(\\\"difference_count\\\", overflow)\\n\\n    def test_report_is_detached_and_input_unchanged(self):\\n        actual = copy.deepcopy(self.export)\\n        actual[\\\"extra\\\"] = {\\\"literal\\\": [\\\"東京\\\"]}\\n        before = copy.deepcopy(actual)\\n        report = explain_replay(actual)\\n        self.assertEqual(actual, before)\\n        report[\\\"differences\\\"][0][\\\"actual\\\"][\\\"value\\\"][\\\"literal\\\"].append(\\\"local note\\\")\\n        self.assertEqual(actual, before)\\n\\n    def test_default_reply_and_actual_cli_match_mismatch(self):\\n        path = self.save()\\n        original_bytes = path.read_bytes()\\n        default = self.cli(path)\\n        self.assertEqual((default.returncode, default.stderr), (0, b\\\"\\\"))\\n        self.assertEqual(default.stdout, (json.dumps(replay_result(self.export), indent=2) + \\\"\\\\n\\\").encode())\\n        matching = self.cli(path, \\\"--explain\\\")\\n        self.assertEqual((matching.returncode, matching.stderr), (0, b\\\"\\\"))\\n        self.assertEqual(json.loads(matching.stdout)[\\\"differences\\\"], [])\\n        self.assertEqual(path.read_bytes(), original_bytes)\\n        self.export[\\\"after\\\"][\\\"version\\\"] += 1\\n        self.save()\\n        mismatch = self.cli(\\\"--explain\\\", path)\\n        self.assertEqual((mismatch.returncode, mismatch.stderr), (1, b\\\"\\\"))\\n        self.assertEqual(json.loads(mismatch.stdout)[\\\"differences\\\"][0][\\\"path\\\"], \\\"/after/version\\\")\\n\\n    def test_explain_refuses_malformed_deep_nonfinite_and_bad_utf8_before_stdout(self):\\n        valid = json.dumps(self.export).encode()\\n        cases = [b\\\"{\\\", b\\\"\\\\xff\\\", b\\\"[\\\" * 2000 + b\\\"0\\\" + b\\\"]\\\" * 2000]\\n        for token in [b\\\"NaN\\\", b\\\"Infinity\\\", b\\\"-Infinity\\\", b\\\"1e999\\\"]:\\n            cases.append(valid[:-1] + b', \\\"extra\\\": ' + token + b\\\"}\\\")\\n        for raw in cases:\\n            with self.subTest(raw_prefix=raw[:16]):\\n                self.path.write_bytes(raw)\\n                result = self.cli(self.path, \\\"--explain\\\")\\n                self.assertEqual(result.returncode, 2)\\n                self.assertEqual(result.stdout, b\\\"\\\")\\n                self.assertIn(b\\\"Replay explanation rejected:\\\", result.stderr)\\n                self.assertNotIn(b\\\"Traceback\\\", result.stderr)\\n                self.assertEqual(self.path.read_bytes(), raw)\\n\\n    def test_explain_actual_byte_bound_and_regular_file_refusal(self):\\n        self.path.write_bytes(b\\\" \\\" * (MAX_BYTES + 1))\\n        result = self.cli(self.path, \\\"--explain\\\")\\n        self.assertEqual((result.returncode, result.stdout), (2, b\\\"\\\"))\\n        self.assertIn(b\\\"Export exceeds 262144 bytes\\\", result.stderr)\\n        for path in [Path(self.directory.name), Path(self.directory.name) / \\\"missing.json\\\"]:\\n            with self.subTest(path=str(path)):\\n                result = self.cli(path, \\\"--explain\\\")\\n                self.assertEqual((result.returncode, result.stdout), (2, b\\\"\\\"))\\n                self.assertNotIn(b\\\"Traceback\\\", result.stderr)\\n        if hasattr(os, \\\"mkfifo\\\"):\\n            fifo = Path(self.directory.name) / \\\"input.fifo\\\"\\n            os.mkfifo(fifo)\\n            result = self.cli(fifo, \\\"--explain\\\")\\n            self.assertEqual((result.returncode, result.stdout), (2, b\\\"\\\"))\\n            self.assertIn(b\\\"regular file\\\", result.stderr)\\n\\n    def test_short_write_and_flush_failure_never_claim_success(self):\\n        self.save()\\n\\n        class Output:\\n            def __init__(self, short=False):\\n                self.short = short\\n                self.text = \\\"\\\"\\n                self.closed = False\\n\\n            def write(self, text):\\n                self.text += text\\n                return len(text) - 1 if self.short else len(text)\\n\\n            def flush(self):\\n                raise OSError(\\\"authored flush failure\\\")\\n\\n            def close(self):\\n                self.closed = True\\n\\n        for short in [False, True]:\\n            output, errors = Output(short), io.StringIO()\\n            self.assertEqual(run_explanation(self.path, MAX_BYTES, output, errors), 2)\\n            self.assertIn(\\\"output failed:\\\", errors.getvalue())\\n            self.assertFalse(output.closed)\\n            self.assertTrue(json.loads(output.text)[\\\"matches\\\"])\\n\\n    @unittest.skipUnless(Path(\\\"/dev/full\\\").exists(), \\\"/dev/full is unavailable\\\")\\n    def test_actual_stdout_failure_is_controlled_and_preserves_input(self):\\n        self.save()\\n        before = self.path.read_bytes()\\n        with open(\\\"/dev/full\\\", \\\"wb\\\") as sink:\\n            result = self.cli(self.path, \\\"--explain\\\", stdout=sink)\\n        self.assertEqual(result.returncode, 2)\\n        self.assertIn(b\\\"Replay explanation output failed:\\\", result.stderr)\\n        self.assertNotIn(b\\\"Traceback\\\", result.stderr)\\n        self.assertNotIn(b\\\"Exception ignored\\\", result.stderr)\\n        self.assertEqual(self.path.read_bytes(), before)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    unittest.main()\\n\"}")
def ident(p):
 b=p.read_bytes();return {'path':str(p),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'git_blob':hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest(),'mode':oct(p.stat().st_mode&0o777)}
def inventory(root):return [ident(p) for p in sorted(root.rglob('*')) if p.is_file()]
